mod krylov;
#[path="../setup/fast.rs"]mod fast;
#[path="../multi/algebra.rs"]mod algebra;
#[path="../orbit-core/sparse.rs"]mod sparse;
use hec_native_ic::{counted,fp::Fp,jac::Curve,poly::Poly,rng::Rng,solve::{Row,SolveStats,Solver,solve_for_last}};
use std::fs;
#[derive(Clone)]struct Eqn{terms:Vec<(usize,u64)>,rhs:u64}
struct Dag{nx:usize,nodes:Vec<Eqn>,closed:Vec<Eqn>}
fn dot(terms:&[(usize,u64)],x:&[u64],f:&Fp)->u64{terms.iter().fold(0,|v,&(i,a)|f.add(v,f.mul(a,x[i])))}
impl Dag{
fn values(&self,x:&[u64],affine:bool,f:&Fp)->Vec<u64>{assert_eq!(x.len(),self.nx);let mut v=x.to_vec();for node in &self.nodes{let a=dot(&node.terms,&v,f);v.push(if affine{f.add(a,node.rhs)}else{a});}v}
fn apply(&self,x:&[u64],f:&Fp)->Vec<u64>{let v=self.values(x,false,f);self.closed.iter().map(|e|dot(&e.terms,&v,f)).collect()}
fn rhs(&self,f:&Fp)->Vec<u64>{let v=self.values(&vec![0;self.nx],true,f);self.closed.iter().map(|e|f.sub(e.rhs,dot(&e.terms,&v,f))).collect()}
fn transpose(&self,z:&[u64],f:&Fp)->Vec<u64>{assert_eq!(z.len(),self.closed.len());let mut bar=vec![0;self.nx+self.nodes.len()];for(e,&v)in self.closed.iter().zip(z){for &(j,a)in &e.terms{bar[j]=f.add(bar[j],f.mul(a,v));}}for(i,e)in self.nodes.iter().enumerate().rev(){let v=bar[self.nx+i];for &(j,a)in &e.terms{bar[j]=f.add(bar[j],f.mul(a,v));}}bar.truncate(self.nx);bar}
fn dense(&self,f:&Fp)->(Vec<Vec<u64>>,Vec<u64>){let mut expressions=vec![];for j in 0..self.nx{let mut e=vec![0;self.nx+1];e[j]=1;expressions.push(e);}for node in &self.nodes{let mut e=vec![0;self.nx+1];e[self.nx]=node.rhs;for &(j,a)in &node.terms{for k in 0..=self.nx{e[k]=f.add(e[k],f.mul(a,expressions[j][k]));}}expressions.push(e);}let mut matrix=vec![];let mut rhs=vec![];for node in &self.closed{let mut e=vec![0;self.nx+1];for &(j,a)in &node.terms{for k in 0..=self.nx{e[k]=f.add(e[k],f.mul(a,expressions[j][k]));}}rhs.push(f.sub(node.rhs,e[self.nx]));e.truncate(self.nx);matrix.push(e);}(matrix,rhs)}
}
fn pack(v:&[u64])->Row{v.iter().enumerate().filter_map(|(j,&a)|(a!=0).then_some((j as u32,a))).collect()}
fn synthetic(){let fixtures=vec![(11,vec![vec![0,0]],false),(11,vec![vec![1,0]],false),(11,vec![vec![0,1],vec![0,2]],true),(5,vec![vec![1,2,0],vec![0,0,1],vec![1,2,1]],true),(11,vec![vec![1,0],vec![0,1],vec![1,1]],true)];for(i,(ell,matrix,exists))in fixtures.into_iter().enumerate(){let f=Fp::new(ell);let n=matrix[0].len();assert_eq!(witness(&matrix,n,&f).is_some(),exists);let apply=|x:&[u64]|matrix.iter().map(|row|row.iter().zip(x).fold(0,|v,(&a,&b)|f.add(v,f.mul(a,b)))).collect::<Vec<_>>();let transpose=|z:&[u64]|(0..n).map(|j|matrix.iter().zip(z).fold(0,|v,(row,&b)|f.add(v,f.mul(row[j],b)))).collect::<Vec<_>>();let(found,stats)=krylov::find(n,matrix.len(),&f,&apply,&transpose,2026113200+i as u64);if let Some(w)=&found{assert!(exists);let mut e=vec![0;n];e[n-1]=1;assert_eq!(transpose(w),e);}if !exists{assert!(found.is_none());}eprintln!("SYNTHETIC\t{i}\treference_exists={exists}\tverified={}\t{stats:?}",found.is_some());}}
fn replay(original:&[(Row,u64)],growth:&[bool],vars:&[Option<usize>],core:u64,old_target:usize,nx:usize,values:&[u64],expected:&[u64],affine:bool,f:&Fp){let mut ci=0;for((row,rhs),&created)in original.iter().skip(1).zip(growth){let mut lhs=0;for &(j,a)in row{let j=j as usize;let x=if j==0{if affine{core}else{0}}else if j==old_target{values[nx-1]}else{values[vars[j].unwrap()]};lhs=f.add(lhs,f.mul(a,x));}if affine{lhs=f.sub(lhs,*rhs);}if created{assert_eq!(lhs,0);}else{assert_eq!(lhs,expected[ci]);ci+=1;}}assert_eq!(ci,expected.len());}
fn witness(matrix:&[Vec<u64>],nx:usize,f:&Fp)->Option<Vec<u64>>{let mut basis:Vec<Option<(Vec<u64>,Vec<u64>)>>=vec![None;nx];for(i,row)in matrix.iter().enumerate(){let mut v=row.clone();let mut w=vec![0;matrix.len()];w[i]=1;for j in 0..nx{let a=v[j];if a==0{continue}if let Some((p,q))=&basis[j]{for k in j..nx{v[k]=f.sub(v[k],f.mul(a,p[k]));}for k in 0..w.len(){w[k]=f.sub(w[k],f.mul(a,q[k]));}}else{let iv=f.inv(a);for x in &mut v{*x=f.mul(*x,iv);}for x in &mut w{*x=f.mul(*x,iv);}if j==nx-1{return Some(w)}basis[j]=Some((v,w));break}}}None}
fn main(){counted::disable();synthetic();let raw=fs::read_to_string("research/hec_residual_span_20261116/incidence-oracle/ROOTS.tsv").unwrap();println!("p\tsm\tseeds\tnodes\tclosed\toperator_terms\tdense_nnz\tk");let(mut panels,mut columns,mut adjoints)=(0,0,0);
for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,z,a)=fast::prepare(&c);let(_,_,degree,lambda)=algebra::certificate(&a,ell);assert_eq!(degree,1);let lambda=lambda.unwrap();let f=Fp::new(ell);let mut map=vec![(usize::MAX,0);fb.len()];let mut ncols=0;
for j in 0..fb.len(){if map[j].0!=usize::MAX{continue}let(mut x,y,mut w)=(fb[j].0,fb[j].1,1);for _ in 0..5{let q=fb.binary_search_by_key(&x,|p|p.0).unwrap();map[q]=(ncols,if fb[q].1==y{w}else{assert_eq!(fb[q].1,c.fp.neg(y));f.neg(w)});x=c.fp.mul(x,z);w=f.mul(w,lambda);}ncols+=1;}
let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026112500^p);for sm in[1,17]{let d=c.mul(&base,sm);let secret=1+rng.below(ell-1);let target=c.mul(&d,secret);let mut input=vec![];for l in raw.lines().skip(1){let v:Vec<_>=l.split('\t').collect();if v[0].parse::<u64>().unwrap()!=p||v[1].parse::<u64>().unwrap()!=sm{continue}let mut row=vec![0;ncols+1];row[ncols]=1;for s in v[5].split(','){let a:Vec<u64>=s.split(':').map(|x|x.parse().unwrap()).collect();let j=fb.binary_search_by_key(&a[1],|p|p.0).unwrap();assert_eq!(map[j].0,a[0]as usize);let w=if a[2]==fb[j].1{map[j].1}else{assert_eq!(a[2],c.fp.neg(fb[j].1));f.neg(map[j].1)};row[map[j].0]=f.add(row[map[j].0],w);}input.push((row,f.neg(v[3].parse::<u64>().unwrap())));}
let mut root=1;while root*root<ncols{root+=1;}for seeds in[2,root,ncols]{let mut dag=Dag{nx:seeds,nodes:vec![],closed:vec![]};let mut vars=vec![None;ncols];for j in 1..seeds{vars[j]=Some(j-1);}let mut known=vec![false;ncols];known[..seeds].fill(true);let mut used=vec![false;input.len()];let core=f.inv(sm);let mut full=sparse::Sparse::new(ncols+1,ell);let mut src=vec![0;ncols+1];src[0]=1;full.insert(&src,core);let mut original=vec![(pack(&src),core)];let mut growth=vec![];
loop{let before=dag.nodes.len();for(index,(row,rhs))in input.iter().enumerate(){if used[index]{continue}let unknown:Vec<_>=(1..ncols).filter(|&j|row[j]!=0&&!known[j]).collect();if unknown.len()>1{continue}let mut terms=vec![(seeds-1,1)];let adjusted=f.sub(*rhs,f.mul(row[0],core));for j in 1..ncols{if row[j]!=0&&known[j]{terms.push((vars[j].unwrap(),row[j]));}}
if let Some(&j)=unknown.first(){let iv=f.inv(row[j]);for term in &mut terms{term.1=f.neg(f.mul(term.1,iv));}vars[j]=Some(seeds+dag.nodes.len());known[j]=true;dag.nodes.push(Eqn{terms,rhs:f.mul(adjusted,iv)});}else{dag.closed.push(Eqn{terms,rhs:adjusted});}growth.push(!unknown.is_empty());used[index]=true;full.insert(row,*rhs);original.push((pack(row),*rhs));}if dag.nodes.len()==before{break}}
let(matrix,rhs)=dag.dense(&f);assert_eq!(dag.rhs(&f),rhs);let offset=dag.values(&vec![0;seeds],true,&f);let neg_rhs:Vec<_>=rhs.iter().map(|&x|f.neg(x)).collect();replay(&original,&growth,&vars,core,ncols,seeds,&offset,&neg_rhs,true,&f);for j in 0..seeds{let mut e=vec![0;seeds];e[j]=1;let column=dag.apply(&e,&f);let values=dag.values(&e,false,&f);replay(&original,&growth,&vars,core,ncols,seeds,&values,&column,false,&f);for(i,row)in matrix.iter().enumerate(){assert_eq!(column[i],row[j]);}columns+=1;}
let mut test=Rng::new(2026113100^p^sm^seeds as u64);for _ in 0..3{let x:Vec<_>=(0..seeds).map(|_|test.below(ell)).collect();let v:Vec<_>=(0..matrix.len()).map(|_|test.below(ell)).collect();let ax=dag.apply(&x,&f);let at=dag.transpose(&v,&f);let lhs=ax.iter().zip(&v).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b)));let rr=x.iter().zip(&at).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b)));assert_eq!(lhs,rr);for j in 0..seeds{let expected=matrix.iter().zip(&v).fold(0,|s,(row,&b)|f.add(s,f.mul(row[j],b)));assert_eq!(at[j],expected);}adjoints+=1;}
let mut schur=sparse::Sparse::new(seeds,ell);for(row,&b)in matrix.iter().zip(&rhs){schur.insert(row,b);}assert_eq!(full.k(),schur.k());let (found,work)=krylov::find(seeds,dag.closed.len(),&f,&|x|dag.apply(x,&f),&|z|dag.transpose(z,&f),2026113200^p^sm^seeds as u64);let passed=if let Some(w)=found{let mut e=vec![0;seeds];e[seeds-1]=1;assert_eq!(dag.transpose(&w,&f),e);let k=w.iter().zip(&rhs).fold(0,|v,(&a,&b)|f.add(v,f.mul(a,b)));assert_eq!(Some(k),schur.k());assert_eq!(c.mul(&d,k),target);true}else{false};eprintln!("KRYLOV\t{p}\t{sm}\t{seeds}\tverified={passed}\t{work:?}");let certificate=witness(&matrix,seeds,&f);assert_eq!(certificate.is_some(),schur.k().is_some());if let Some(w)=certificate{let mut expected=vec![0;seeds];expected[seeds-1]=1;assert_eq!(dag.transpose(&w,&f),expected);let k=w.iter().zip(&rhs).fold(0,|s,(&a,&b)|f.add(s,f.mul(a,b)));assert_eq!(Some(k),schur.k());}let mut stats=SolveStats::default();assert_eq!(solve_for_last(&original,ncols,ell,Solver::Fast,&[],&mut stats),schur.k());if let Some(k)=schur.k(){assert_eq!(k,secret);assert_eq!(c.mul(&d,k),target);}let edges:usize=dag.nodes.iter().chain(&dag.closed).map(|e|e.terms.len()).sum();let dense_nnz=matrix.iter().flatten().filter(|&&x|x!=0).count();println!("{p}\t{sm}\t{seeds}\t{}\t{}\t{edges}\t{dense_nnz}\t{}",dag.nodes.len(),dag.closed.len(),schur.k().map_or("none".into(),|k|k.to_string()));panels+=1;
}}}assert_eq!(panels,18);eprintln!("panels={panels} full_basis_columns={columns} adjoint_checks={adjoints} all_dense_rhs_transpose_originalSparse_nativeFast_target_witness_and_group_checks_pass=true retained_support_oracle=true no_producer_cost_claim=true");}
